import React, { useState, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import NavBar from '../Components/NavBar'
import Footer from '../Components/Footer'
import './advertisements.css'

const posters = [
  { id: 1, title: 'T-shirt Design Course', imageUrl: '/Images/home1.jpeg', description: 'Master the art of T-shirt design...', tag: 'Beginner Friendly' },
  { id: 2, title: 'Batik Techniques', imageUrl: '/Images/home2.jpeg', description: 'Explore traditional and modern Batik methods...', tag: 'Intermediate' },
  { id: 3, title: 'Screen Printing Workshop', imageUrl: '/Images/home2.jpeg', description: 'Hands-on training for multi-color screen printing...', tag: 'Workshop' }
]

const courseOptions = [
  { name: 'T-Shirt Course', price: 1500, key: 'courseTshirt' },
  { name: 'Batik Course', price: 2000, key: 'courseBatik' },
  { name: 'Screen Printing Course', price: 2500, key: 'courseScreen' },
]

const itemOptions = [
  { name: 'Pattern Making Book', price: 500, key: 'itemBook' },
  { name: 'Video Course', price: 1000, key: 'itemVideo' },
  { name: 'T-shirt 3 Pattern Set', price: 800, key: 'itemPatternSet' },
  { name: 'Starter Ink Kit', price: 700, key: 'itemInkKit' },
]

export default function Advertisements() {
  const navigate = useNavigate()

  // --- Form State Management ---
  const [participateChecked, setParticipateChecked] = useState(false)
  const [selections, setSelections] = useState({
    courseTshirt: false,
    courseBatik: false,
    courseScreen: false,
    itemBook: false,
    itemVideo: false,
    itemPatternSet: false,
    itemInkKit: false,
  })
  const [userDetails, setUserDetails] = useState({
    name: '',
    email: '',
    phone: ''
  })

  const goToDetail = (poster) => {
    navigate(`/advertisement/${poster.id}`, { state: poster })
  }

  const handleSelectionChange = (key) => {
    setSelections(prev => ({
      ...prev,
      [key]: !prev[key]
    }))
  }

  const handleUserDetailChange = (e) => {
    setUserDetails(prev => ({
      ...prev,
      [e.target.name]: e.target.value
    }))
  }
  
  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form Submitted!', { selections, userDetails, total: calculatedTotal });
    alert(`Registration submitted! Total Fee: LKR ${calculatedTotal}`);
    // Here you would typically send data to an API
  };


  // --- Calculation Logic (Memoized for performance) ---
  const calculatedTotal = useMemo(() => {
    let total = 0
    // Sum courses
    courseOptions.forEach(option => {
      if (selections[option.key]) {
        total += option.price
      }
    })
    // Sum items
    itemOptions.forEach(option => {
      if (selections[option.key]) {
        total += option.price
      }
    })
    return total
  }, [selections])


  // --- Form Rendering Helper ---
  const renderCheckboxes = (options, title) => (
    <div className="form-group">
      <h3 className="form-subtitle">{title}</h3>
      {options.map((option) => (
        <label key={option.key} className="checkbox-label">
          <input
            type="checkbox"
            checked={selections[option.key]}
            onChange={() => handleSelectionChange(option.key)}
          />
          {option.name} <span className="item-price"> (LKR {option.price})</span>
        </label>
      ))}
    </div>
  )

  return (
    <div className="advertisements-page">
      <NavBar />
      
      <main className="content-area">
        {/* Poster Section (Unchanged) */}
        <header className="page-header">
          <h1>Creative Workshops & Courses 🎨</h1>
          <p>Explore a range of hands-on courses in textile design and printing!</p>
        </header>

        <section className="posters-grid">
          {posters.map((poster) => (
            <article 
              key={poster.id} 
              className="poster-card"
              onClick={() => goToDetail(poster)} // Re-added navigation on card click
            >
              <div className="poster-image-wrapper">
                <img src={poster.imageUrl} alt={poster.title} className="poster-image" />
              </div>
              <div className="poster-info">
                <h3 className="poster-title">{poster.title}</h3>
                <p className="poster-description">{poster.description}</p>
                {poster.tag && <p className="poster-tag">**{poster.tag}**</p>}
              </div>
            </article>
          ))}
        </section>

        {/* --- Registration Form Section --- */}
        <section className="registration-section">
          <h2 className="section-title">Course Registration</h2>

          {/* Conditional Participation Checkbox */}
          <div className="form-group participate-toggle">
            <label className="checkbox-label participate-label">
              <input
                type="checkbox"
                checked={participateChecked}
                onChange={() => setParticipateChecked(!participateChecked)}
              />
              **I want to participate to th Course**
            </label>
          </div>

          {/* Conditional Form Display */}
          {participateChecked && (
            <form onSubmit={handleSubmit} className="registration-form">
              <div className="form-selection-group">
                
                {/* 1. Course Selection */}
                {renderCheckboxes(courseOptions, 'Select the Course')}

                <div className="form-divider"></div>

                {/* 2. Item Purchase */}
                {renderCheckboxes(itemOptions, 'I want to buy')}
              </div>
              
              {/* Total Value Display */}
              <div className="total-value-box">
                **Total Value:** <span className="total-amount">LKR {calculatedTotal.toFixed(2)}</span>
              </div>

              <div className="form-divider"></div>

              {/* 3. Personal Details */}
              <div className="personal-details-group">
                <h3 className="form-subtitle">Personal Details</h3>
                <input
                  type="text"
                  name="name"
                  placeholder="Full Name"
                  value={userDetails.name}
                  onChange={handleUserDetailChange}
                  required
                />
                <input
                  type="email"
                  name="email"
                  placeholder="Email Address"
                  value={userDetails.email}
                  onChange={handleUserDetailChange}
                  required
                />
                <input
                  type="tel"
                  name="phone"
                  placeholder="Phone Number"
                  value={userDetails.phone}
                  onChange={handleUserDetailChange}
                  required
                />
              </div>

              <button type="submit" className="submit-btn">
                Register & Submit
              </button>
            </form>
          )}
        </section>

      </main>

      <Footer />
    </div>
  )
}
